package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.articles.EntityDedupService;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import tools.jackson.databind.node.ObjectNode;
import tools.jackson.databind.json.JsonMapper;

/** Entirely fictional pure input/result/event facts; this test grants no native storage or source admission. */
class EntityHeatDedupOriginTest {
    SourceDedupFragmentProofTest h;SourcePartitionPlanner.Plan plan;SourcePartitionPlanner.Chunk chunk;SourceDedupFragmentProof fragment;
    @BeforeEach void setup(){h=new SourceDedupFragmentProofTest();plan=h.plan(h.universe);chunk=plan.chunks().getFirst();fragment=h.read(plan,h.universe,chunk,h.handoff(plan,h.universe,chunk));}
    JdbcEntityHeatEvents.Event event(int index){var fact=fragment.members().get(index);var item=CanonicalJson.parse(fragment.result().payloadJson()).get("items").get(index);var snapshot=CanonicalJson.parse(chunk.snapshotJson());var input=h.input(chunk);var member=FrozenMemberBindings.read(snapshot,input).get(fact.itemId());var command=new EntityDedupService.Automatic(fact.itemId(),member.expectedRevision(),item.get("decision").asText(),member.category(),member.identityKey(),item.get("candidate_entity_id").isNull()?null:item.get("candidate_entity_id").asText(),input.candidatesByItem().getOrDefault(fact.itemId(),Set.of()).stream().sorted().toList(),item.get("suggested_title").asText(),item.get("suggested_summary").isNull()?null:item.get("suggested_summary").asText(),item.get("reason").asText());var n=JsonMapper.shared().createObjectNode().put("schema_version","entity-decision-v2").put("request_hash",EntityDedupService.automaticFingerprint(command)).put("operation",fact.entityId()==null?"needs_review":"existing").put("item_id",fact.itemId()).putNull("old_entity_id").put("new_entity_id",fact.entityId());var result=n.putObject("result").put("item_id",fact.itemId()).put("entity_id",fact.entityId()).put("state",fact.state()).put("new_contribution",fact.entityId()!=null);if(fact.entityId()==null)result.putNull("occurrence_count");else result.put("occurrence_count",1);var heats=n.putArray("entity_heat_snapshots");if(fact.entityId()!=null)heats.add(new EntityHeatSnapshot(fact.entityId(),"news_tech",3,1L,"Fictional title",null,Instant.parse("2026-01-01T08:00:00Z"),LocalDate.of(2026,1,1),false).toJson());String body=JdbcFrozenInputs.canonical(n),target=JdbcFrozenInputs.canonical(JsonMapper.shared().createObjectNode().put("kind","source_run_item").put("id",fact.itemId()));return new JdbcEntityHeatEvents.Event(EntityHeatDedupOrigin.eventId(fragment.rootId(),fragment.result().resultHash(),fact.itemId()),"analysis-worker",command.reason(),target,body,HexFormat.of().formatHex(JdbcGenerationLineage.hash(body)),Instant.parse("2026-01-01T21:00:00Z"));}
    JdbcEntityHeatEvents.Event change(JdbcEntityHeatEvents.Event event,ObjectNode body){String raw=JdbcFrozenInputs.canonical(body);return new JdbcEntityHeatEvents.Event(event.id(),event.actor(),event.reason(),event.targetJson(),raw,HexFormat.of().formatHex(JdbcGenerationLineage.hash(raw)),event.actedAt());}
    @Test void OriginalNewSuggestionReusedEntityExistingDecisionAndExactSourceInputAreLinked(){var event=event(0);var value=EntityHeatDedupOrigin.bind(event,chunk,fragment);assertEquals(fragment.members().getFirst().entityId(),value.entityId());assertEquals(chunk.inputHash(),value.inputHash());assertEquals(fragment.result().resultHash(),value.resultHash());assertEquals(event.id(),value.eventId());assertEquals(h.universe.sourceId(),value.sourceId());assertEquals(h.universe.runId(),value.runId());var raw=CanonicalJson.parse(chunk.snapshotJson()).get("members").get(0);assertEquals(JdbcFrozenInputs.canonical(raw.get("body")),value.originalBodyJson());assertEquals(CanonicalJson.hash(CanonicalJson.Domain.CONTENT,raw.get("body")),value.originalBodyHash());assertFalse(value.toString().contains(value.itemId()));}
    @Test void OriginalExistingChoiceAndNeedsReviewHaveExactCommandAndNoInventedEntity(){assertNotNull(EntityHeatDedupOrigin.bind(event(1),chunk,fragment).entityId());assertNull(EntityHeatDedupOrigin.bind(event(2),chunk,fragment).entityId());}
    @Test void RehashedDifferentRequestTargetOrMemberDecisionCannotBorrowTheOriginalInput(){var original=event(0);var body=(ObjectNode)CanonicalJson.parse(original.payloadJson());body.put("request_hash","b".repeat(64));var wrongRequest=change(original,body);assertThrows(RuntimeException.class,()->EntityHeatDedupOrigin.bind(wrongRequest,chunk,fragment));body=(ObjectNode)CanonicalJson.parse(original.payloadJson());body.put("new_entity_id","fictional-alien");((ObjectNode)body.get("result")).put("entity_id","fictional-alien");((ObjectNode)body.get("entity_heat_snapshots").get(0)).put("entity_id","fictional-alien");var alien=change(original,body);assertThrows(RuntimeException.class,()->EntityHeatDedupOrigin.bind(alien,chunk,fragment));var other=new JdbcEntityHeatEvents.Event(original.id(),original.actor(),original.reason(),JdbcFrozenInputs.canonical(JsonMapper.shared().createObjectNode().put("kind","source_run_item").put("id","fictional-alien")),original.payloadJson(),original.payloadHash(),original.actedAt());assertThrows(RuntimeException.class,()->EntityHeatDedupOrigin.bind(other,chunk,fragment));}
    @Test void OtherActorActionRootResultAndEventBodyHashCannotGrantTheLink(){var original=event(0);for(var other:List.of(new JdbcEntityHeatEvents.Event(original.id(),"fictional-owner",original.reason(),original.targetJson(),original.payloadJson(),original.payloadHash(),original.actedAt()),new JdbcEntityHeatEvents.Event("c".repeat(64),original.actor(),original.reason(),original.targetJson(),original.payloadJson(),original.payloadHash(),original.actedAt()),new JdbcEntityHeatEvents.Event(original.id(),original.actor(),original.reason(),original.targetJson(),original.payloadJson(),"b".repeat(64),original.actedAt()),new JdbcEntityHeatEvents.Event(original.id(),original.actor(),"Fictional different reason",original.targetJson(),original.payloadJson(),original.payloadHash(),original.actedAt())))assertThrows(RuntimeException.class,()->EntityHeatDedupOrigin.bind(other,chunk,fragment));assertNotEquals(original.id(),EntityHeatDedupOrigin.eventId("fictional-other-root",fragment.result().resultHash(),fragment.members().getFirst().itemId()));assertNotEquals(original.id(),EntityHeatDedupOrigin.eventId(fragment.rootId(),"b".repeat(64),fragment.members().getFirst().itemId()));}
    @Test void DifferentChunkAndLegacyOrManualEventsCannotBeInferredAsAnOriginalAutomaticEvent(){var other=new SourcePartitionPlanner.Chunk(chunk.stagePart(),"fictional-other-root",chunk.itemIds(),chunk.snapshotJson(),chunk.inputHash(),chunk.requestJson());assertThrows(RuntimeException.class,()->EntityHeatDedupOrigin.bind(event(0),other,fragment));var original=event(0);var body=(ObjectNode)CanonicalJson.parse(original.payloadJson());body.put("schema_version","entity-decision-v1").remove("entity_heat_snapshots");var legacy=change(original,body);assertThrows(RuntimeException.class,()->EntityHeatDedupOrigin.bind(legacy,chunk,fragment));body=(ObjectNode)CanonicalJson.parse(original.payloadJson());body.put("old_entity_id",body.get("new_entity_id").asText()).put("operation","split");var manual=change(original,body);assertThrows(RuntimeException.class,()->EntityHeatDedupOrigin.bind(manual,chunk,fragment));}
}
